 * Verschlüsselt den Klartext mit dem Schlüssel und gibt den Geheimtext zurück 
 * @param klartext 
 * @param schluessel 
 * @return verschlüsselter text 
 */
public static String verschluesseln(String klartext, int schluessel)
{
    String geheimtext = "";   // zunächst noch leer
    klartext = klartext.toUpperCase();  // in Großbuchstaben umwandeln
    for (int i=0; i<klartext.length(); i++)
    {
        // für alle einzelnen Buchstaben:
        // verschieben und an den Geheimtext anhängen
        char buchstabe = klartext.charAt(i);
        geheimtext += verschieben(buchstabe, schluessel);
    }
    return geheimtext;
}","language":"java","showLineNumbers":false},"id":"f2bba85b-2846-46e2-835b-f2fc6db4daa1"},{"plugin":"text","state":[{"type":"h","level":3,"children":[{"text":"Schritt 3: "},{"type":"a","href":"/39871","children":[{"text":"Methode"}]},{"text":" "entschluesseln" erstellen"}]}],"id":"cf7d5655-eab2-4a4c-b8e2-728eabc2699a"},{"plugin":"text","state":[{"type":"p","children":[{"text":"Wieder bekommt die Methode einen Text als String und einen Schlüssel als Integer-Wert übergeben und gibt einen String zurück, nämlich den entschlüsselten Text. Der Code für die Methode sieht also wie folgt aus:"}]}],"id":"9b2937d7-e27f-41eb-86b1-b25a9c40b9e0"},{"plugin":"highlight","state":{"code":"/**
 * Entschlüsselt den Geheimtext mit dem angegebenen Schlüssel 
 * @param geheimtext 
 * @param schluessel 
 * @return entschlüsselter Text 
 */
public static String entschluesseln(String geheimtext, int schluessel)
{
    return verschluesseln(geheimtext, 26-schluessel);
}","language":"java","showLineNumbers":false},"id":"26d0a60e-f68f-4ffe-bc07-c1584b048980"},{"plugin":"text","state":[{"type":"h","level":3,"children":[{"text":"Zusammenfassend: Test im Hauptprogramm"}]},{"type":"p","children":[{"text":"In der Main-Methode schreibst du einen kurzer Text und probierst einmal aus, ob die Ver- und Entschlüsselung funktioniert: "}]}],"id":"2ab8b8b1-81e5-431c-81bb-8e21faa433e3"},{"plugin":"highlight","state":{"code":"public static void main(String[] args)
{
    int schluessel = 3;
    String klartext = "JuhuEsfunktioniert";
    String geheimtext = verschluesseln(klartext, schluessel);
    System.out.println("Klartext:   " + klartext + " -> " + geheimtext);
    String entschluesselt = entschluesseln(geheimtext, schluessel);
    System.out.println("Geheimtext: " + geheimtext + " -> " + entschluesselt);
}","language":"java","showLineNumbers":false},"id":"317d96bb-fcc9-4644-a851-29898ade2d7a"},{"plugin":"text","state":[{"type":"p","children":[{"text":""}]},{"type":"p","children":[{"text":""}]}],"id":"972ce998-fdde-4b36-acef-b630d26a1303"}],"id":"c209f4e1-389c-49c1-b18a-2a19ee045d3c"}},"id":"d817d6cf-b987-4dc0-8f09-ad221f616dc6"}},"id":"0b778c9a-0482-4332-b7ae-6fc0f9ba8a56"}}
